private boolean testWithFeeFromFilter(Coin tradeAmount,Coin actualFeeValue,Coin feeFromFilter,Param minFeeParam){
  long actualFeeAsLong=actualFeeValue.value;
  long feeFromFilterAsLong;
  try {
    feeFromFilterAsLong=calculateFee(tradeAmount,feeFromFilter,minFeeParam).value;
  } catch (IllegalArgumentException e) {
    // 处理异常，例如记录日志或返回默认值
    return false;
  }
  double deviation=actualFeeAsLong / (double)feeFromFilterAsLong;
  return deviation > 0.7;
}
